(() => {
  'use strict';
  const el=id=>document.getElementById(id),state={csrf:''};
  async function call(path,method='GET',body){const headers={Accept:'application/json'};if(method!=='GET')headers['X-CSRF-Token']=state.csrf;if(body!==undefined)headers['Content-Type']='application/json';const response=await fetch('/conscious/api/vendor/'+path,{method,credentials:'same-origin',cache:'no-store',headers,body:body===undefined?undefined:JSON.stringify(body)});const data=await response.json().catch(()=>({}));if(!response.ok||!data.success)throw Error(data.message||'Payout account request failed.');return data;}
  function row(label,value){const wrap=document.createElement('div');wrap.className='vc-info-row';const name=document.createElement('span');name.textContent=label;const info=document.createElement('strong');info.textContent=String(value??'—');wrap.append(name,info);return wrap;}
  function status(text,error=false){el('vpb-status').textContent=text;el('vpb-status').className='vc-status '+(error?'warning':'success');}
  function toast(text,error=false){if(typeof window.vendorToast==='function')window.vendorToast(text,error?'error':'success');}
  function saved(message){const node=document.querySelector('[data-save-confirmation]');if(node){node.hidden=false;node.replaceChildren();const icon=document.createElement('i');icon.className='fa-solid fa-circle-check';node.append(icon,document.createTextNode(message));}status(message);toast(message);}
  async function load(){try{const identity=await call('auth/me.php');state.csrf=identity.csrf_token||'';const finance=await call('finance-summary.php');const banks=el('vpb-banks');banks.replaceChildren();if(!finance.bank_accounts?.length)banks.textContent='No payout bank account has been submitted.';else finance.bank_accounts.forEach(bank=>banks.append(row('Account ending '+bank.account_last4,bank.verification_status?.replaceAll('_',' '))));status('Payout account loaded.');}catch(error){status(error.message,true);toast(error.message,true);}}
  el('vpb-bank-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;form.classList.add('was-validated');if(!form.checkValidity()){form.querySelector(':invalid')?.focus();status('Complete the highlighted bank details.',true);return;}const values=Object.fromEntries(new FormData(form));const proof=values.bank_proof;delete values.bank_proof;if(values.account_number!==values.account_confirm){el('vpb-account-confirm').setCustomValidity('Account numbers do not match.');el('vpb-account-confirm').reportValidity();status('Account numbers do not match.',true);return;}if(!proof||proof.size<1||proof.size>5242880||!['image/jpeg','image/png','application/pdf'].includes(proof.type)){status('Choose a JPG, PNG or PDF bank proof under 5 MB.',true);return;}const button=event.submitter;button.disabled=true;try{await call('bank-account.php','POST',values);const upload=new FormData();upload.append('document_type','bank_proof');upload.append('file',proof);const response=await fetch('/conscious/api/vendor/documents.php',{method:'POST',credentials:'same-origin',headers:{Accept:'application/json','X-CSRF-Token':state.csrf},body:upload});const result=await response.json().catch(()=>({}));if(!response.ok||!result.success)throw Error(result.message||'Bank details were saved, but proof upload failed.');form.reset();form.classList.remove('was-validated');await load();saved('Bank details and proof submitted for admin review.');}catch(error){status(error.message,true);toast(error.message,true);}finally{button.disabled=false;}});
  el('vpb-account-confirm').addEventListener('input',event=>event.target.setCustomValidity(''));
  load();
})();
